-- ----------------------------
-- QMS 检验项目表
-- ----------------------------
CREATE TABLE IF NOT EXISTS "qms_inspection_item" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(64) NOT NULL,
    "name" varchar(255) NOT NULL,
    "type" int NOT NULL,
    "method" int NOT NULL,
    "standard" varchar(500) DEFAULT NULL,
    "target" varchar(100) DEFAULT NULL,
    "upper_limit" decimal(20,4) DEFAULT NULL,
    "lower_limit" decimal(20,4) DEFAULT NULL,
    "unit" varchar(32) DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "status" int DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

-- ----------------------------
-- QMS 检验单表
-- ----------------------------
CREATE TABLE IF NOT EXISTS "qms_inspection_order" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "version" bigint NOT NULL DEFAULT 0,
    "order_no" varchar(64) NOT NULL,
    "type" int NOT NULL,
    "supplier_id" bigint DEFAULT NULL,
    "batch_no" varchar(64) DEFAULT NULL,
    "work_order_id" bigint DEFAULT NULL,
    "product_id" bigint DEFAULT NULL,
    "inspector" varchar(64) DEFAULT NULL,
    "inspect_time" timestamp DEFAULT NULL,
    "status" int DEFAULT 10,
    "acceptance_quantity" int DEFAULT NULL COMMENT 'AQL 接收数 Ac',
    "reject_quantity" int DEFAULT NULL COMMENT 'AQL 拒收数 Re',
    "biz_type" varchar(32) DEFAULT NULL COMMENT '业务类型',
    "biz_id" bigint DEFAULT NULL COMMENT '业务单据 ID',
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

-- ----------------------------
-- QMS 检验记录表
-- ----------------------------
CREATE TABLE IF NOT EXISTS "qms_inspection_record" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" bigint NOT NULL,
    "item_id" bigint NOT NULL,
    "measured_value" varchar(100) DEFAULT NULL,
    "result" int DEFAULT NULL,
    "severity" int NOT NULL DEFAULT 30 COMMENT '缺陷严重度：10-致命(CRITICAL)/20-严重(MAJOR)/30-轻微(MINOR)',
    "inspector" varchar(64) DEFAULT NULL,
    "inspect_time" timestamp DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

-- ----------------------------
-- QMS CAPA 纠正预防措施文档表
-- ----------------------------
CREATE TABLE IF NOT EXISTS "qms_ncr_document" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "ncr_no" varchar(64) DEFAULT NULL,
    "source" int DEFAULT NULL,
    "inspection_order_id" bigint DEFAULT NULL,
    "product_id" bigint DEFAULT NULL,
    "supplier_id" bigint DEFAULT NULL,
    "work_order_id" bigint DEFAULT NULL,
    "defect_description" clob DEFAULT NULL,
    "defect_level" int DEFAULT NULL,
    "quantity" decimal(20,4) DEFAULT NULL,
    "disposition" int DEFAULT NULL,
    "status" int DEFAULT 10,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "qms_capa_document" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "capa_no" varchar(64) NOT NULL,
    "source" int NOT NULL,
    "priority" int DEFAULT NULL,
    "stage" int DEFAULT 10,
    "problem" clob DEFAULT NULL,
    "cause" clob DEFAULT NULL,
    "root_cause_analysis" clob DEFAULT NULL,
    "corrective_action" clob DEFAULT NULL,
    "preventive_action" clob DEFAULT NULL,
    "responsible_person" varchar(64) DEFAULT NULL,
    "due_date" timestamp DEFAULT NULL,
    "close_date" timestamp DEFAULT NULL,
    "status" int DEFAULT 10,
    "verification_result" int DEFAULT NULL,
    "verification_comment" clob DEFAULT NULL,
    "verified_by" varchar(64) DEFAULT NULL,
    "verified_time" timestamp DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

-- ----------------------------
-- QMS 8D 报告表
-- ----------------------------
CREATE TABLE IF NOT EXISTS "qms_eight_d_report" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "report_no" varchar(64) NOT NULL,
    "title" varchar(255) DEFAULT NULL,
    "ncr_id" bigint DEFAULT NULL,
    "capa_id" bigint DEFAULT NULL,
    "status" int DEFAULT 0,
    "d1_team_members" clob DEFAULT NULL,
    "d2_problem_description" clob DEFAULT NULL,
    "d3_interim_action" clob DEFAULT NULL,
    "d4_root_cause" clob DEFAULT NULL,
    "d5_permanent_action" clob DEFAULT NULL,
    "d6_implementation_result" clob DEFAULT NULL,
    "d7_prevention_action" clob DEFAULT NULL,
    "d8_team_recognition" clob DEFAULT NULL,
    "close_time" timestamp DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

-- ----------------------------
-- QMS 受控文档主表
-- ----------------------------
CREATE TABLE IF NOT EXISTS "qms_document" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "doc_no" varchar(64) NOT NULL,
    "title" varchar(255) NOT NULL,
    "doc_type" int NOT NULL,
    "version" varchar(32) NOT NULL DEFAULT '1.0',
    "status" int NOT NULL DEFAULT 10,
    "effective_date" date DEFAULT NULL,
    "expiry_date" date DEFAULT NULL,
    "approver_id" bigint DEFAULT NULL,
    "approve_date" timestamp DEFAULT NULL,
    "owner_dept_id" bigint DEFAULT NULL,
    "file_url" varchar(500) DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "sort" int DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

-- ----------------------------
-- QMS 客户投诉表
-- ----------------------------
CREATE TABLE IF NOT EXISTS "qms_customer_complaint" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "complaint_no" varchar(64) NOT NULL,
    "customer_id" bigint DEFAULT NULL,
    "customer_name" varchar(255) DEFAULT NULL,
    "product_id" bigint DEFAULT NULL,
    "product_name" varchar(255) DEFAULT NULL,
    "complaint_content" clob DEFAULT NULL,
    "complaint_date" date DEFAULT NULL,
    "root_cause" clob DEFAULT NULL,
    "impact_scope" varchar(1000) DEFAULT NULL,
    "handle_type" int DEFAULT NULL,
    "handle_action" clob DEFAULT NULL,
    "eight_d_id" bigint DEFAULT NULL,
    "status" int NOT NULL DEFAULT 10,
    "close_time" timestamp DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

